-- Copie a paginii de vânzare GoodSleep de pe Shopify (reduxio.ro/products/goodsleep, șablonul goodsleep-oldstyle), reconstruită din blocurile
-- noastre, ca CIORNĂ pe domeniul comanda.reduxio.ro, la adresa /goodsleep. Nu se vede pe domeniu până nu o publici din editor.
-- Rulează-l o singură dată. Formularul e legat de landing page-ul REAL "good-sleep" (produs activ, cu pixel): comenzile de pe pagină sunt
-- comenzi reale, deci la test folosește ?notrack=1 și marchează comanda ca test în primele 3 minute, ca de obicei.
-- Diferențe față de Shopify: hero-ul e primul cadru al GIF-ului (GIF-ul are 2,6 MB; pentru animație pune un bloc Video MP4);
-- cutiile cu chenar albastru sunt acum text și liste fără chenar; nota despre cosmetice spune GoodSleep (pe Shopify scria SlimGel) și duce
-- la /retur-produse-cosmetice; comentarea clienților: verifică că sunt reale.
insert into landing_page_content (organization_id, domain_id, landing_page_id, slug, title, background, blocks, status, is_home, layout)
select d.organization_id, d.id, (select lp.id from landing_pages lp where lp.slug = 'good-sleep' and lp.organization_id = d.organization_id limit 1), 'goodsleep', 'GoodSleep', '#ffffff', $json$[{"type":"topbar_timer","label":"REDUCERE","discount":"-70 lei","discountBg":"#0bba71","discountColor":"#ffffff","expiresLabel":"Oferta expiră în","offerName":"OFERTĂ BLACK FRIDAY","days":0,"size":14,"sticky":true,"radius":0,"bg":"#202020","color":"#ffffff"},{"type":"image","src":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/first-frame-goodsleep1_q50.webp?v=1792349558","alt":"GoodSleep","width":480,"height":480,"radius":0,"inset":0,"maxWidth":500,"href":null,"label":"Hero (primul cadru)"},{"type":"text","text":"GoodSleep","align":"center","size":"2xl","color":"#222222","bold":true,"label":"Titlu"},{"type":"text","text":"**un roll-on pentru cei care doresc să adoarmă repede și fără gânduri**","align":"center","size":"lg","color":"#333333","bold":false,"label":"Subtitlu"},{"type":"text","text":"😓 PROBLEMA REALĂ","align":"center","size":"xl","color":"#1e3a8a","bold":true,"label":"Problema"},{"type":"list","items":["**Somnul întrerupe** îți afectează sănătatea","**Cearcănele și aspectul obosit** devin tot mai vizibile","**Lipsa somnului îți scade concentrarea** și bunăstarea zilnică","**Nervozitatea și stresul** cresc fără să îți dai seama","În timp, **calitatea vieții scade** fără să realizezi"],"icon":"•","iconColor":"#1e3a8a","color":"#111111","size":"base","label":"Probleme"},{"type":"text","text":"👉 **Somnul afectat nu rămâne doar o problemă de noapte — se vede în fiecare zi.**","align":"left","size":"base","color":"#1e40af","bold":false,"label":"Notă problemă"},{"type":"image","src":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/Product_integration_into_202604211306_q60.webp?v=1792349221","alt":"GoodSleep","width":500,"height":500,"radius":0,"inset":0,"maxWidth":null,"href":null,"label":"Imagine produs"},{"type":"text","text":"✨ SOLUȚIA: GoodSleep","align":"center","size":"xl","color":"#1e3a8a","bold":true,"label":"Soluția"},{"type":"list","items":["**Liniștește mintea** atunci când nu se oprește seara","**Te ajută să adormi mai ușor**, fără agitație și tensiune","**Susține un somn mai profund și mai odihnitor**","**Reduce starea de oboseală** acumulată de la o noapte la alta","**Îți readuce energia** și claritatea de dimineață"],"icon":"•","iconColor":"#1e3a8a","color":"#111111","size":"base","label":"Beneficii"},{"type":"text","text":"👉 **Când somnul revine, se schimbă tot: cum te simți, cum arăți și cum funcționezi zi de zi.**","align":"left","size":"base","color":"#1e40af","bold":false,"label":"Notă soluție"},{"type":"image","src":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/Woman_before_and_202604211311_q50.webp?v=1792349972","alt":"Înainte și după","width":500,"height":500,"radius":0,"inset":0,"maxWidth":null,"href":null,"label":"Înainte / după"},{"type":"form","landingSlug":"good-sleep","org":"reduxio-srl","thankYouPath":"/thank-you","label":"Formular"},{"type":"fb_comments","title":"Ce spun clienții noștri","items":[{"name":"Maria Donțu","text":"Adorm mult mai ușor seara. Înainte stăteam cu ochii în tavan și nu puteam să mă liniștesc. Acum simt că mă relaxez mult mai repede după ce îl folosesc.","when":"3 zile","avatar":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/fb21.webp?v=1789408862","reactions":["like","love"],"count":32,"verified":false,"reply":null},{"name":"Elena Crețu","text":"Nu mai sunt atât de agitată noaptea. Mă trezeam des și îmi era greu să adorm la loc. De când îl folosesc, nopțile sunt mai liniștite.","when":"5 zile","avatar":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/fb11.webp?v=1789408862","reactions":["like","love"],"count":18,"verified":false,"reply":null},{"name":"Ana Marinescu","text":"Dimineața mă simt mai odihnită. Nu mai am senzația aia de oboseală constantă. Parcă mă ridic mai ușor din pat.","when":"1 săptămână","avatar":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/fb9.webp?v=1789408862","reactions":["like","love"],"count":24,"verified":false,"reply":null},{"name":"Cristina Dumitru","text":"Chiar mă ajută să mă relaxez. Îl folosesc înainte de culcare și simt că mă liniștesc mai repede. Pentru mine a devenit rutină.","when":"2 săptămâni","avatar":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/fb14.webp?v=1789408862","reactions":["like","love"],"count":41,"verified":false,"reply":null}],"cardBg":"#ffffff","bubbleBg":"#f0f2f5","color":"#1c1e21","size":15,"showActions":true,"label":"Comentarii"},{"type":"text","text":"🌙 Ingrediente & cum te ajută să dormi mai ușor","align":"center","size":"xl","color":"#1e3a8a","bold":true,"label":"Ingrediente"},{"type":"text","text":"Un blend de uleiuri esențiale selectate pentru a **susține relaxarea** și a crea starea potrivită pentru somn.","align":"center","size":"base","color":"#111111","bold":false,"label":"Ingrediente: intro"},{"type":"list","items":["🌿 **Lavandă** — ajută la calmarea minții și reducerea agitației de seară","🌼 **Mușețel** — susține relaxarea și liniștea înainte de culcare","🌳 **Lemn de santal & Tămâie** — creează o stare profundă de calm și echilibru","🍊 **Citrice (Portocală, Bergamotă)** — reduc tensiunea acumulată și îmbunătățesc starea generală","❄️ **Mentă & Eucalipt** — oferă o senzație de prospețime și respirație ușoară"],"icon":"•","iconColor":"#1e3a8a","color":"#111111","size":"base","label":"Ingrediente: listă"},{"type":"text","text":"👉 Combinația lor creează un moment de liniște — primul pas către un somn mai odihnitor.","align":"center","size":"base","color":"#1e40af","bold":false,"label":"Ingrediente: notă"},{"type":"faq","title":"Întrebări frecvente","items":[{"q":"Cum se folosește GoodSleep?","a":"Se aplică pe încheieturi, gât sau tâmple, cu câteva minute înainte de culcare. Inhalează aroma și lasă corpul să intre treptat într-o stare de relaxare."},{"q":"Mă ajută să adorm mai repede?","a":"GoodSleep este creat pentru a susține relaxarea înainte de somn. Prin utilizare constantă, te poate ajuta să intri mai ușor într-o stare de somn."},{"q":"După cât timp se simte efectul?","a":"Efectul de relaxare poate fi resimțit chiar din primele utilizări, însă rezultatele depind de rutină și consistență."},{"q":"Creează dependență?","a":"Nu. GoodSleep este un produs pe bază de uleiuri esențiale, fără substanțe care creează dependență."},{"q":"Este potrivit pentru femei și bărbați?","a":"Da, GoodSleep poate fi folosit atât de femei, cât și de bărbați care vor să își îmbunătățească rutina de somn."},{"q":"Cât durează un flacon?","a":"În funcție de utilizare, un flacon poate ajunge aproximativ 3–4 săptămâni."},{"q":"Cum se face plata și livrarea?","a":"Livrarea se face rapid prin curier, direct la ușa dumneavoastră. **Plata se face exclusiv ramburs (la livrare)**, în momentul în care primiți coletul și aveți produsul în mână. Nu este necesar niciun card online."}],"openFirst":false,"accent":"#333333","label":"Întrebări frecvente"},{"type":"html","html":"<div style=\"margin:12px 16px;padding:14px;border-radius:16px;border:1px solid rgba(255,90,0,.14);background:linear-gradient(180deg,#fff 0%,#fff7f2 100%);text-align:center;font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:rgba(0,0,0,.88)\"><div style=\"font-weight:900;font-size:12px;letter-spacing:.1em;text-transform:uppercase;margin-bottom:8px\">Important: GoodSleep este un produs cosmetic</div><div style=\"font-size:13px;line-height:1.45;color:rgba(0,0,0,.78)\">Prin plasarea comenzii confirm că sunt de acord cu <br><a href=\"/retur-produse-cosmetice\" style=\"color:#ff5a00;font-weight:900;text-decoration:underline\">politica de retur pentru produse cosmetice</a><br> și înțeleg că produsele desigilate sau utilizate nu pot fi returnate.</div></div>","label":"Notă retur cosmetice"},{"type":"html","html":"<div style=\"margin:24px 16px;padding:20px;background:#fff6cc;border-left:5px solid #F5D547;border-right:5px solid #F5D547;border-radius:12px;text-align:center;color:#333;box-shadow:0 2px 10px rgba(0,0,0,.05)\"><h3 style=\"font-size:22px;color:#000;margin:0 0 12px\">Dorești factura ?</h3><p style=\"font-size:16px;line-height:1.6;margin:0 0 10px\">Trimite-ne un mesaj la <a href=\"mailto:contact@reduxio.ro\" style=\"color:#ff5722;font-weight:600;text-decoration:underline\">contact@reduxio.ro</a> și ți-o livrăm rapid pe email.</p><p style=\"font-size:16px;line-height:1.6;margin:0\">REDUXIO este despre grija pentru tine și pentru natură – nu tipărim facturile pe hârtie, ca să protejăm mediul. 🌿</p></div>","label":"Factura"},{"type":"shared_footer","footerId":null},{"type":"sticky_footer","text":"COMANDĂ ACUM  →","href":"#comanda","bg":"#0bba71","color":"#ffffff"}]$json$::jsonb, 'draft', false, 'narrow'
from page_domains d
where d.hostname = 'comanda.reduxio.ro' and d.status in ('verified', 'active')
